INSERT INTO `alert_rule_catalog` (`rule_code`, `alert_type`, `source`, `default_severity`, `authority`, `description`, `is_enabled`, `created_at`, `updated_at`) VALUES
  ('BATTERY_PERCENT_LOW', 'LOW_BATTERY', 'TELEMETRY', 'CRITICAL', 'PROJECT_SIMULATION_POLICY', 'Battery percentage remains at or below the critical project threshold for the required consecutive samples.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('BATTERY_VOLTAGE_LOW', 'BATTERY_VOLTAGE_LOW', 'TELEMETRY', 'CRITICAL', 'PROJECT_SIMULATION_POLICY', 'Battery voltage remains at or below the critical project threshold under simulated load.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('BATTERY_OVERHEAT', 'BATTERY_OVERHEAT', 'TELEMETRY', 'CRITICAL', 'PROJECT_SIMULATION_POLICY', 'Battery temperature reaches the critical project threshold for consecutive samples.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('MOTOR_OVERHEAT', 'MOTOR_OVERHEAT', 'TELEMETRY', 'CRITICAL', 'PROJECT_SIMULATION_POLICY', 'At least one motor temperature reaches the critical project threshold for consecutive samples.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('MOTOR_RPM_ANOMALY', 'MOTOR_RPM_ANOMALY', 'TELEMETRY', 'WARNING', 'PROJECT_SIMULATION_POLICY', 'One motor RPM deviates from the four-motor median beyond the configured project threshold.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('EXCESSIVE_VIBRATION', 'EXCESSIVE_VIBRATION', 'TELEMETRY', 'CRITICAL', 'PROJECT_SIMULATION_POLICY', 'Synthetic airframe vibration exceeds the configured project threshold.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('PROPELLER_DAMAGE_SUSPECTED', 'PROPELLER_DAMAGE_SUSPECTED', 'TELEMETRY', 'CRITICAL', 'PROJECT_SIMULATION_POLICY', 'Critical RPM imbalance and vibration occur together; operator inspection is required.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('GPS_LOST', 'GPS_LOST', 'TELEMETRY', 'CRITICAL', 'PROJECT_SIMULATION_POLICY', 'GNSS quality remains LOST for the configured consecutive samples.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('COMMUNICATION_LOST', 'COMMUNICATION_LOST', 'TELEMETRY', 'CRITICAL', 'PROJECT_SIMULATION_POLICY', 'Control-link signal remains at or below the configured project threshold.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('HEARTBEAT_TIMEOUT', 'DRONE_OFFLINE', 'SYSTEM', 'CRITICAL', 'SYSTEM_LIFECYCLE', 'An online or in-flight drone misses the backend heartbeat timeout; deliberate power-off does not trigger this rule.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('MISSION_FAILED', 'MISSION_FAILED', 'SYSTEM', 'CRITICAL', 'SYSTEM_LIFECYCLE', 'A flight attempt ends before route completion because of a critical incident.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('RESTRICTED_FLIGHT_ZONE', 'RESTRICTED_FLIGHT_ZONE', 'ROUTE', 'CRITICAL', 'SYSTEM_LIFECYCLE', 'Route validation intersects an active restricted polygon or violates the allowed operating boundary.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('UNSAFE_WEATHER', 'UNSAFE_WEATHER', 'WEATHER', 'CRITICAL', 'PROJECT_SIMULATION_POLICY', 'The worst route weather sample evaluates to UNSAFE and blocks flight creation.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00'),
  ('WEATHER_CAUTION', 'WEATHER_CAUTION', 'WEATHER', 'WARNING', 'PROJECT_SIMULATION_POLICY', 'The worst route weather sample evaluates to CAUTION and requires explicit user acknowledgement.', TRUE, '2026-09-19 10:00:00', '2026-09-19 10:00:00');
INSERT INTO `alerts` (`id`, `alert_code`, `flight_id`, `mission_id`, `component_id`, `source`, `rule_code`, `severity`, `type`, `message`, `metric_name`, `observed_value`, `threshold_value`, `unit`, `status`, `detected_at`, `last_observed_at`, `resolved_at`, `resolution_note`, `created_at`, `updated_at`) VALUES
  (1, 'ALT-001', 5, 15, 24, 'TELEMETRY', 'BATTERY_PERCENT_LOW', 'CRITICAL', 'LOW_BATTERY', 'Battery reserve reached 10%; return-to-home was initiated.', 'battery_percent', 10, 10, '%', 'RESOLVED', '2026-07-07 06:09:46.000', '2026-07-07 06:09:58.000', '2026-07-07 06:29:58.000', 'Aircraft landed and the battery pack was replaced.', '2026-07-07 06:09:46', '2026-07-07 06:29:58'),
  (2, 'ALT-002', 6, 16, 24, 'TELEMETRY', 'BATTERY_VOLTAGE_LOW', 'CRITICAL', 'BATTERY_VOLTAGE_LOW', 'Battery pack voltage sagged to 13.15 V under load.', 'battery_voltage_v', 13.15, 13.2, 'V', 'RESOLVED', '2026-07-08 07:08:52.000', '2026-07-08 07:09:58.000', '2026-07-08 07:29:58.000', 'Aircraft landed; the simulated pack was removed from service.', '2026-07-08 07:08:52', '2026-07-08 07:29:58'),
  (3, 'ALT-003', 6, 16, NULL, 'SYSTEM', 'MISSION_FAILED', 'CRITICAL', 'MISSION_FAILED', 'Flight FLT-006 ended before completing the route: Flight aborted after abnormal battery voltage sag.', NULL, NULL, NULL, NULL, 'RESOLVED', '2026-07-08 07:09:58.000', '2026-07-08 07:09:58.000', '2026-07-08 07:29:58.000', 'Incident reviewed and historical mission record closed.', '2026-07-08 07:09:58', '2026-07-08 07:29:58'),
  (4, 'ALT-004', 7, 17, 24, 'TELEMETRY', 'BATTERY_OVERHEAT', 'CRITICAL', 'BATTERY_OVERHEAT', 'Battery temperature reached 60.47 °C.', 'battery_temperature_c', 60.47, 60, '°C', 'RESOLVED', '2026-07-09 01:08:58.000', '2026-07-09 01:09:58.000', '2026-07-09 01:29:58.000', 'Aircraft landed and the simulated battery cooled below the recovery threshold.', '2026-07-09 01:08:58', '2026-07-09 01:29:58'),
  (5, 'ALT-005', 8, 15, 24, 'TELEMETRY', 'BATTERY_PERCENT_LOW', 'CRITICAL', 'LOW_BATTERY', 'Battery reserve reached 10%; return-to-home was initiated.', 'battery_percent', 10, 10, '%', 'RESOLVED', '2026-07-10 02:09:46.000', '2026-07-10 02:09:58.000', '2026-07-10 02:29:58.000', 'Aircraft landed and the battery pack was replaced.', '2026-07-10 02:09:46', '2026-07-10 02:29:58'),
  (6, 'ALT-006', 9, 18, 34, 'TELEMETRY', 'MOTOR_OVERHEAT', 'CRITICAL', 'MOTOR_OVERHEAT', 'The front-left motor temperature reached 80.64 °C.', 'motor_temperature_fl_c', 80.64, 80, '°C', 'RESOLVED', '2026-07-11 03:08:24.000', '2026-07-11 03:09:58.000', '2026-07-11 03:29:58.000', 'Motor cooled after landing and passed the simulated inspection.', '2026-07-11 03:08:24', '2026-07-11 03:29:58'),
  (7, 'ALT-007', 10, 19, 35, 'TELEMETRY', 'MOTOR_RPM_ANOMALY', 'WARNING', 'MOTOR_RPM_ANOMALY', 'The front-right motor RPM deviated 15.53% from the four-motor median; inspect the propulsion system.', 'motor_rpm_fr_deviation_percent', 15.53, 15, '%', 'RESOLVED', '2026-07-12 04:06:58.000', '2026-07-12 04:09:58.000', '2026-07-12 04:29:58.000', 'Simulated motor and propeller inspection completed.', '2026-07-12 04:06:58', '2026-07-12 04:29:58'),
  (8, 'ALT-008', 10, 19, 31, 'TELEMETRY', 'EXCESSIVE_VIBRATION', 'CRITICAL', 'EXCESSIVE_VIBRATION', 'Airframe vibration reached 2.579 g during the front-right propulsion incident.', 'vibration_g', 2.579, 2.5, 'g', 'RESOLVED', '2026-07-12 04:08:22.000', '2026-07-12 04:09:58.000', '2026-07-12 04:29:58.000', 'Simulated damaged propeller was replaced.', '2026-07-12 04:08:22', '2026-07-12 04:29:58'),
  (9, 'ALT-009', 10, 19, 31, 'TELEMETRY', 'PROPELLER_DAMAGE_SUSPECTED', 'CRITICAL', 'PROPELLER_DAMAGE_SUSPECTED', 'Suspected front-right propeller damage: critical RPM imbalance and vibration occurred together.', 'composite_propulsion_fault', NULL, NULL, NULL, 'RESOLVED', '2026-07-12 04:08:22.000', '2026-07-12 04:09:58.000', '2026-07-12 04:29:58.000', 'Manual simulated inspection confirmed replacement and closed the alert.', '2026-07-12 04:08:22', '2026-07-12 04:29:58'),
  (10, 'ALT-010', 10, 19, NULL, 'SYSTEM', 'MISSION_FAILED', 'CRITICAL', 'MISSION_FAILED', 'Flight FLT-010 ended before completing the route: Emergency landing after RPM imbalance and excessive vibration indicated suspected front-right propeller damage.', NULL, NULL, NULL, NULL, 'RESOLVED', '2026-07-12 04:09:58.000', '2026-07-12 04:09:58.000', '2026-07-12 04:29:58.000', 'Incident reviewed and historical mission record closed.', '2026-07-12 04:09:58', '2026-07-12 04:29:58'),
